grid = [[1]*W for _ in range(H)]

# Fill original values
for (r, c), v in [(0, 3), (1, 4), (1, 5), (2, 4), (2, 5)].items():
    grid[r][c] = v

# For max value, find the diagonal
max_val = 6
max_r, max_c = 2, 4  # position of value 6
diag_val = max_r - max_c  # = -2
print(f"Fill all (r,c) where r-c = {diag_val}")

# Fill max_val on the diagonal r-c = -2
for r in range(H):
    for c in range(W):
        if r - c == diag_val:
            grid[r][c] = max_val

# But also preserve non-6 values!
# Let me redo this

grid = [[1]*W for _ in range(H)]

# Start with all 1s
for r in range(H):
    for c in range(W):
        grid[r][c] = 1

# Copy non-1 values
input_values = {
    (0, 3): 3,
    (1, 4): 3,
    (1, 5): 2,
    (2, 4): 6,
    (2, 5): 2,
}

for r in range(H):
    for c in range(W):
        if (r, c) in input_values:
            grid[r][c] = input_values[(r, c)]

# Now fill the diagonal with max_val (only if it wasn't already there)
